const seedEnvironment = z.object({
  ADMIN_EMAIL: z.email(),
  ADMIN_PASSWORD: z.string().min(12),
  ADMIN_NAME: z.string().trim().min(2).max(120).default("PrepLoom Admin"),
});

async function seedAdmin() {
  const environment = seedEnvironment.parse(process.env);
  const email = environment.ADMIN_EMAIL.trim().toLowerCase();
  const passwordHash = await bcrypt.hash(environment.ADMIN_PASSWORD, 12);
  await prisma.admin.upsert({
    where: { email },
    update: { name: environment.ADMIN_NAME, passwordHash, isActive: true },
    create: { email, name: environment.ADMIN_NAME, passwordHash },
  });
}

async function seedContent() {
  let addedTopics = 0;
  let addedQuestions = 0;
  for (const entry of seedSubjects) {
    const subject = await prisma.subject.upsert({
      where: { slug: entry.slug },
      update: {},
      create: {
        slug: entry.slug,
        name: entry.name,
        description: entry.description,
      },
    });
    const topics = await prisma.topic.createMany({
      data: entry.topics.map((topic) => ({ ...topic, subjectId: subject.id })),
      skipDuplicates: true,
    });
    addedTopics += topics.count;
    const questions = await prisma.question.createMany({
      data: entry.questions.map((question) => ({
        ...question,
        subjectId: subject.id,
      })),
      skipDuplicates: true,
    });
    addedQuestions += questions.count;
  }
  let addedQuizzes = 0;
  for (const entry of seedQuizzes) {
    const subject = await prisma.subject.findUniqueOrThrow({
      where: { slug: entry.subjectSlug },
    });
    const existing = await prisma.quiz.findUnique({
      where: { subjectId_slug: { subjectId: subject.id, slug: entry.slug } },
    });
    if (existing) continue;
    await prisma.quiz.create({
      data: {
        subjectId: subject.id,
        slug: entry.slug,
        title: entry.title,
        summary: entry.summary,
        position: entry.position,
        questions: { create: entry.questions },
      },
    });
    addedQuizzes++;
  }
  console.info(
    "Seed ready: " +
      seedSubjects.length +
      " subjects, " +
      addedTopics +
      " new topics, " +
      addedQuestions +
      " new questions, " +
      addedQuizzes +
      " new quizzes.",
  );
}

async function main() {
  await seedAdmin();
  await seedContent();
}

main()
  .catch((error: unknown) => {
    console.error("Could not seed the database.", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
